from turtle import *

rafael = Turtle()      # Lager et skilpaddeobjekt
rafael.shape("turtle") # Bruker metoden "shape" på objektet
rafael.color("red")    # Bruker metoden "color" på objektet

rafael.forward(100)    # Bruker metoden "forward" på objektet
rafael.left(90)        # Bruker metoden "left" på objektet
rafael.forward(100)
rafael.left(90)
rafael.forward(100)